      { question: "Why should you never look directly at the sun?", answer: "Because the sun is so bright it can damage your eyes permanently", options: ["It is fine to look at the sun", "Because the sun is so bright it can damage your eyes permanently", "Only on cloudy days is it dangerous", "The sun is not bright enough to hurt you"] },
      { question: "What would Earth be like without the sun?", answer: "A frozen, dark ball of rock with no life — the sun provides the light and heat that make life possible", options: ["Exactly the same", "A frozen, dark ball of rock with no life — the sun provides the light and heat that make life possible", "We would just use flashlights", "Earth does not need the sun"] }
